script:
(function () {
  'use strict';
  // One loan paid weekly, biweekly, semimonthly, monthly, quarterly or annually.
  //   Periodic rate i = annual rate / f (f payments a year).
  //   Same term: payment P = L x i / (1 - (1 + i)^-(years x f)) (L / n at 0%).
  //   Accelerated: P = monthly payment / 4 (weekly), / 2 (biweekly, semimonthly), x 3 (quarterly),
  //   x 12 (annually); payoff found by running the balance down, last payment = balance + interest.
  //   Interest is the sum of balance x i over every period, so totals carry no rounding drift.
  // Checked in Node (scratchpad tests/w3b6_loans/apf.test.js): $20,000 at 7.5% over 5 years ->
  //   $400.76 monthly, total interest $4,045.54 (closed form 60 x 400.7589 - 20,000); biweekly
  //   same-term payment equals the closed form with i = 7.5%/26, n = 130; accelerated monthly equals
  //   same-term monthly; accelerated biweekly payoff count matches n = -ln(1 - L i / P) / ln(1 + i)
  //   rounded up; 0% rate gives zero interest everywhere; the year-end balances of each schedule
  //   match the closed-form remaining balance L(1+i)^k - P((1+i)^k - 1)/i.
  var FREQS = [
    { key: 'weekly', name: 'Weekly', f: 52, split: 1 / 4 },
    { key: 'biweekly', name: 'Biweekly', f: 26, split: 1 / 2 },
    { key: 'semimonthly', name: 'Semimonthly', f: 24, split: 1 / 2 },
    { key: 'monthly', name: 'Monthly', f: 12, split: 1 },
    { key: 'quarterly', name: 'Quarterly', f: 4, split: 3 },
    { key: 'annually', name: 'Annually', f: 1, split: 12 }
  ];
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }
  function read(id) {
    var raw = String(el(id).value).trim();
    if (raw === '') return NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function payment(loan, i, n) { return i === 0 ? loan / n : loan * i / (1 - Math.pow(1 + i, -n)); }

  // Runs the balance down; returns payments made, interest and the balance at each year end.
  function run(loan, rate, f, pay, maxN) {
    var i = rate / f, bal = loan, interest = 0, count = 0, yearEnd = [], lastPay = pay, capped = false;
    while (bal > 0.000001 && count < maxN) {
      var charge = bal * i;
      count++;
      interest += charge;
      if (bal + charge <= pay * (1 + 1e-4) + 0.005) { lastPay = bal + charge; bal = 0; }
      else if (count === maxN) { capped = pay < bal + charge; lastPay = bal + charge; bal = 0; }
      else bal = bal + charge - pay;
      if (count % f === 0) yearEnd.push(bal);
    }
    if (count % f !== 0) yearEnd.push(bal);
    return { count: count, interest: interest, yearEnd: yearEnd, lastPay: lastPay, total: loan + interest, capped: capped };
  }

  function compare(loan, rate, years, method) {
    var monthly = payment(loan, rate / 12, years * 12);
    return FREQS.map(function (q) {
      var i = rate / q.f, n = years * q.f;
      var pay = method === 'split' ? monthly * q.split : payment(loan, i, n);
      // Paying less often than monthly (quarterly, annually) can take longer than the term; stop at 100 years.
      var r = run(loan, rate, q.f, pay, method === 'split' ? 100 * q.f : n);
      return { key: q.key, name: q.name, f: q.f, payment: pay, perYear: pay * q.f, count: r.count, interest: r.interest,
        total: r.total, yearEnd: r.yearEnd, months: Math.ceil(r.count * 12 / q.f - 1e-9), capped: r.capped };
    });
  }

  function span(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + ' yr' + (y === 1 ? '' : 's'));
    if (m) parts.push(m + ' mo' + (m === 1 ? '' : 's'));
    return parts.join(' ') || '0 mos';
  }
  function signed(x) {
    if (Math.abs(x) < 0.005) return '–';
    return (x > 0 ? '+' : '−') + money.format(Math.abs(x));
  }

  function clear() {
    ['apfMonthly', 'apfBest', 'apfSaved', 'apfSummary'].forEach(function (id) { setText(id, '–'); });
    el('apfCompare').innerHTML = ''; el('apfBalance').innerHTML = ''; el('apfBalanceHead').innerHTML = '';
  }

  function update() {
    var loan = read('apfLoan'), rate = read('apfRate'), years = read('apfYears'), method = el('apfMethod').value;
    var err = el('apfError'), msg = '';
    if ([loan, rate, years].some(isNaN)) msg = 'Enter the loan amount, interest rate and term.';
    else if (loan <= 0 || loan > 1e10) msg = 'Enter a loan amount above $0.';
    else if (rate < 0 || rate > 50) msg = 'Enter an interest rate from 0% to 50%.';
    else if (years < 1 || years > 40 || years % 1 !== 0) msg = 'Enter a term of 1 to 40 whole years.';
    err.hidden = !msg;
    err.textContent = msg;
    if (msg) { clear(); return; }

    var rows = compare(loan, rate / 100, years, method);
    var monthly = rows[3], best = rows[0];
    rows.forEach(function (r) { if (!r.capped && r.interest < best.interest - 0.005) best = r; });
    setText('apfMonthly', money.format(monthly.payment));
    setText('apfBest', money.format(best.interest));
    setText('apfSaved', money.format(Math.max(0, monthly.interest - best.interest)));
    var s;
    if (rate === 0) s = 'At 0% every schedule costs nothing in interest; only the size and timing of the payments differ.';
    else {
      s = best.name + ' payments cost the least interest: ' + money.format(best.interest) + ', against ' + money.format(monthly.interest) + ' paying monthly.';
      if (method === 'split') {
        var bw = rows[1];
        s += ' Paying half the monthly payment every two weeks adds the equivalent of one extra monthly payment a year and clears the loan in ' +
          span(bw.months) + ' instead of ' + span(monthly.months) + '.';
        if (rows[4].months > monthly.months) s += ' Quarterly and annual payments take longer, because interest builds up for longer between payments.';
      } else {
        s += ' With the term fixed, more frequent payments save interest because each one reduces the balance a little sooner.';
      }
    }
    setText('apfSummary', s);
    el('apfCompare').innerHTML = rows.map(function (r) {
      if (r.capped) return '<tr><th scope="row">' + r.name + '</th><td>' + money.format(r.payment) + '</td><td>' + money.format(r.perYear) +
        '</td><td>–</td><td>Not within 100 yrs</td><td>–</td><td>–</td></tr>';
      return '<tr><th scope="row">' + r.name + '</th><td>' + money.format(r.payment) + '</td><td>' + money.format(r.perYear) + '</td><td>' + r.count +
        '</td><td>' + span(r.months) + '</td><td>' + money.format(r.interest) + '</td><td>' + signed(r.interest - monthly.interest) + '</td></tr>';
    }).join('');
    el('apfBalanceHead').innerHTML = '<tr><th scope="col">Year</th>' + rows.map(function (r) { return '<th scope="col">' + r.name + '</th>'; }).join('') + '</tr>';
    var yearsShown = 0;
    rows.forEach(function (r) { if (!r.capped) yearsShown = Math.max(yearsShown, r.yearEnd.length); });
    var html = [];
    for (var y = 0; y < yearsShown; y++) {
      html.push('<tr><td>' + (y + 1) + '</td>' + rows.map(function (r) {
        var b = y < r.yearEnd.length ? r.yearEnd[y] : 0;
        return '<td>' + money.format(Math.max(0, b)) + '</td>';
      }).join('') + '</tr>');
    }
    el('apfBalance').innerHTML = html.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('apfForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
